  str_dispatch_book_bookname_3000 = "Nameless Mercenary's Notes",
  str_dispatch_book_bookname_4000 = "Dream's Covenant",
  str_dispatch_book_bookname_5000 = "Rediesel Recipe",
  str_dispatch_book_bookname_6000 = "Northland Geographica",
  str_dispatch_book_bookname_7000 = "Doomsday Chronicles",
  str_dispatch_book_bookname_8000 = "Unknown Ancient Tomes",
  str_dispatch_book_bookname_9000 = "An Adventurer's Voyage",
  str_dispatch_book_bookname_10000 = "Illumina Social Guidelines",
  str_dispatch_book_bookname_11000 = "Ada and the Colossus",
  str_dispatch_book_bookname_12000 = "Journey's Dawn",
  str_dispatch_book_bookname_13000 = "Snowland Ballad",
  str_dispatch_book_bookname_14000 = "Surat-menyurat antara Rosa dan M&M",
  str_dispatch_book_bookname_15000 = "Mrs. Red Mercury",
  str_dispatch_book_bookdes_1000 = "Kitab yang konon pernah disimpan di Lumopolis Temple. Karena isinya sukar dipahami dan rahasia, kitab ini tidak pernah diterbitkan untuk dibaca khalayak umum. Setelah muncul kembali dari ketiadaan yang misterius selama berabad-abad, kitab ini ditulis ulang dan diedarkan secara massal dan menjadi bacaan yang dikenal semua orang.",
  str_dispatch_book_bookdes_2000 = "Buku ini berkaitan dengan sebagian sejarah tanah air Demi-human, Secret Territory, termasuk sejarah berdirinya, kejatuhannya dari kemakmuran akibat serangan Eclipsite, dan pendudukan pemungkas oleh Eclipsite tersebut. Dari buku ini, kita bisa memperoleh pemahaman umum seputar tragedi yang menimpa ratusan tahun silam, serta memperdalam pemahaman kita tentang struktur kekuatan dunia kita saat ini.",
  str_dispatch_book_bookdes_3000 = "Catatan seorang tentara bayaran yang tak diketahui namanya tentang karier melelahkannya sebagai petarung sewaan, serta upayanya untuk membentuk tim tentara bayaran pribadi. Tahun ketika jurnal ini ditulis tidak diketahui, tetapi tampaknya cukup modern. Hanya nama bulan yang disertakan dalam judul setiap entri. Tulisan tangannya rapi dan mudah dibaca, dan sejumput optimisme bisa terbaca di antara kalimat-kalimatnya.",
  str_dispatch_book_bookdes_4000 = [[
Semacam mimpi, semacam lolongan, semacam keputusasaan. Penuh keluhan yang tak terselesaikan dari zaman kuno, serta kecemasan ganjil tentang masa depan... Namun, yang benar-benar membuat isi buku ini membosankan dan tak berarti adalah karena buku ini tak lebih dari tiruan berkualitas rendah. Terlepas dari kesungguhan upaya kita untuk memahaminya, tidak ada yang benar-benar bisa menggambarkan Truth yang agung, kuno, dan tertidur.
...Benarkah demikian?]],
  str_dispatch_book_bookdes_5000 = "Pengembara paruh waktu dan pencinta boga purnawaktu, Iron Chef of Rediesel Desert, dan penyuka daging Eclipsite—inilah gambaran singkat diriku! Jika kamu tersesat di gurun, berarti kamu benar-benar berani atau benar-benar bodoh. Namun, jangan cemas, karena selama kamu memiliki buku resep Uncle Johnny, kamu tidak akan sampai terpaksa makan pasir karena sekarat! Pasir sulit dikeluarkan dari pencernaan, tahu? Ha ha ha! Dasar manusia konyol!",
  str_dispatch_book_bookdes_6000 = [[
Tidak banyak orang yang tahu bahwa, selain menjadi Lumopolis Guide, Ms. Blanc juga seorang pengembara rajin dan pemandu wisata berbakat (meski tur berpemandu eksklusifnya ditujukan hanya untuk tamu yang paling akrab dan dihormatinya). Kami berkesempatan mewawancarai Ms. Blanc, dan buku ini adalah kompilasi dari topik-topik yang kami bahas.
Pelanggan yang telah memesan buku ini di salah satu toko buku afiliasi kami akan menerima kartu pos Ms. Blanc spesial, dan 10 pembeli yang beruntung akan mendapatkan hadiah berupa kartu pos bertanda tangan.]],
  str_dispatch_book_bookdes_7000 = "Doomsday Chronicles adalah kompilasi catatan tertulis yang konon berasal dari peradaban kuno yang mendiami pinggiran Northland. Setelah buku ini awalnya digali, para peneliti menyimpulkan bahwa kerusakan besar pada catatan ini memang disengaja, dan bukanlah akibat dimakan waktu. Untungnya, beberapa bagian dalam kitab ini berada dalam kondisi yang relatif lengkap. Bagian-bagiannya yang tak lengkap tampaknya meramalkan bencana kiamat...",
  str_dispatch_book_bookdes_8000 = "Konon, Unknown Ancient Tomes ditulis oleh Chief of Science and Tech pertama dari Illumina. Kitab ini adalah kompilasi penelitian ilmiah dan teknologi bertahun-tahun tentang peradaban kuno, dan catatan eksperimen yang tak terhitung jumlahnya yang kini hilang ditelan zaman. Dengan kepergian Chief ini, Unknown Ancient Tomes pun entah ada di mana. Saat ini, yang masih beredar hanya sebagian kecil dari pengetahuan yang ditemukan di dalam Tome, meskipun keasliannya sering dipertanyakan.",
  str_dispatch_book_bookdes_9000 = "\"An Adventurer's Voyage\" adalah petualangan fiksi karangan seorang novelis kelahiran Umbraton. Buku ini menceritakan tentang seorang pemuda yang mengarungi lautan bersama angkatan laut kerajaan, menghadapi segala jenis monster dan misteri, dan pada akhirnya menemukan harta karun legendaris serta membela kerajaannya dari serangan monster laut. Ada banyak bab dalam cerita ini, tetapi yang tersisa dalam jilid pertama hanyalah bab berikut ini.",
  str_dispatch_book_bookdes_10000 = "Illumina Federation dari Astra, umumnya dikenal sebagai Illumina, yang ibu kotanya berada di Gannon City. Ditulis oleh Illumina Federation Bureau of Administration dengan bekerja sama dengan konsultan dari Illumina Federal Council, militer Illumina Federation, dan Illumina Research Center, buku ini bertujuan memberikan pedoman yang tepat bagi semua warga Illumina yang baru terintegrasi.",
  str_dispatch_book_bookdes_11000 = "Ada and the Colossus, ditulis oleh Hayden, adalah dongeng populer di Eraveil dan merupakan inspirasi bagi Caelestite. Buku ini menceritakan tentang seorang gadis Caelestite bernama Ada yang menjalin hubungan telepati dengan Kaz, Colossus terlemah, dan meninggalkan Eraveil untuk menjelajahi dunia. Lewat petualangan mereka, sang penulis menjelaskan beragam konsep seperti Eoria, hari dan malam tiada akhir, Aurorian, Eclipsite, dan lainnya.",
  str_dispatch_book_bookdes_12000 = "Mina adalah seorang pengelana terkenal yang jurnalnya banyak dibaca oleh para Aurorian di Astra. Dalam salah satu catatan perjalanannya, Mina mengutarakan penyesalan yang dia simpan di dalam hatinya sejak masih kecil. Ketika tumbuh di sebuah desa di sepanjang tepi Gold River, dia menjalin persahabatan yang erat dengan seorang kesatria dari Lumopolis bernama Sheriozha. Namun, pada akhirnya, mereka harus berpisah. Dalam cerita yang berjudul Journey's Dawn ini, selubung pada Lumo Knights dan Luminatics akan tersingkap satu per satu.",
  str_dispatch_book_bookdes_13000 = "Ini adalah cerita yang beredar di Northland. Meskipun tak ada satu pun yang mengetahui kebenarannya, seorang penyanyi yang berkelana di Northland mengumpulkannya dalam sebuah antologi... Dua anak yatim piatu Aurorian berambut pirang dari bagian yang tidak diketahui bertemu di sebuah desa Northland dan menjalin ikatan yang kuat dengan saling membantu dan menerima. Selain itu, kita juga akan melihat sekilas kehidupan sehari-hari Aurorian di Northland dalam cerita.",
  str_dispatch_book_bookdes_14000 = "Ini adalah kumpulan surat-menyurat antara Rosa si Teknisi di Rediesel Desert dan M&M Second-hand Parts Store di Umbraton, tetapi ada banyak surat yang hilang. Untuk mendapatkan komponen murah untuk proyek modifikasinya, Rosa menghubungi toko komponen M&M di Umbraton, dan mereka punya komponen yang dibutuhkannya. Kerja sama mereka berlangsung selama lebih dari satu dekade, hingga akhirnya Rosa meninggal. Melalui surat-surat ini, kita bisa mengintip kehidupan sehari-hari di Rediesel Desert dan Umbraton.",
  str_dispatch_book_bookdes_15000 = "Yvonne adalah seorang novelis terkenal yang dikenal karena menggabungkan peristiwa kehidupan nyata dan orang-orang dengan fiksi. Nyonya Red Mercury adalah salah satu cerpennya yang lebih terkenal. Ini menceritakan kisah legendaris Ny. Red Mercury, pemimpin guild di Umbraton. Buku itu dicetak ulang berkali-kali. Redaktur penanggung jawab edisi kedua dapat memverifikasi keberadaan orang dan peristiwa yang disebutkan dalam cerita, dan hasil penelitiannya dimasukkan dalam kata penutup. Buku ini memungkinkan pembaca melihat sekilas seperti apa kehidupan di Umbraton beberapa dekade yang lalu.",
  str_dispatch_book_ce = "{1} Volume",
